sdkInitPattern.typescript:
import { CosmosClient } from '@azure/cosmos';
import { DefaultAzureCredential } from '@azure/identity';

const credential = new DefaultAzureCredential();
const client = new CosmosClient({ endpoint: process.env.AZURE_COSMOS_ENDPOINT!, aadCredentials: credential });
const db = client.database(process.env.AZURE_COSMOS_DATABASE!);
const container = db.container(process.env.AZURE_COSMOS_CONTAINER!);
